@push('scripts')<script>$(function(){$('.js-production-return-action').on('click',function(){const b=$(this),a=b.data('action');Swal.fire({icon:'warning',title:a==='approve'?'อนุมัติใบรับคืนวัตถุดิบ?':a==='post'?'ลง Stock ใบรับคืนวัตถุดิบ?':a==='reverse'?'ยกเลิกเอกสารรับคืน?':a==='cancel'?'ยกเลิกเอกสารรับคืน?':'ลบร่างใบรับคืน?',text:a==='reverse'?'ระบบจะสร้างรายการย้อนกลับเพื่อแก้ผลกระทบ Stock':undefined,input:['cancel','reverse'].includes(a)?'textarea':undefined,inputLabel:['cancel','reverse'].includes(a)?'เหตุผลการยกเลิกเอกสาร':undefined,showCancelButton:true,confirmButtonText:a==='delete'?'ลบร่าง':(['cancel','reverse'].includes(a)?'ยืนยันยกเลิกเอกสาร':'ยืนยัน'),cancelButtonText:'กลับ'}).then(x=>{if(!x.isConfirmed)return;const data={_token:$('meta[name=csrf-token]').attr('content')};if(['cancel','reverse'].includes(a))data.reason=x.value;$.ajax({url:b.data('url'),type:a==='delete'?'DELETE':'POST',data}).done(r=>{Swal.fire({icon:'success',text:r.msg,timer:1100,showConfirmButton:false}).then(()=>location.href=r.redirect||location.href)}).fail(x=>Swal.fire({icon:'error',text:x.responseJSON?.message||'ดำเนินการไม่สำเร็จ'}));});});});</script>@endpush
